const urls = [1,2,3].map(page => `https://federation.ccdi.cancer.gov/api/v1/subject?sex=F&page=${page}&per_page=10`);
const out = [];
for (const url of urls) {
  try {
    const res = await fetch(url);
    const text = await res.text();
    let payload;
    try { payload = JSON.parse(text); } catch { payload = text.slice(0, 500); }
    out.push({ url, ok: res.ok, status: res.status, link: res.headers.get('link'), contentType: res.headers.get('content-type'), payload });
    if (!res.ok) break;
    const data = payload && typeof payload === 'object' ? payload.data : undefined;
    if (!Array.isArray(data) || data.length < 10) break;
  } catch (err) {
    out.push({ url, ok: false, error: String(err && err.message || err) });
    break;
  }
}
nodeRepl.write(JSON.stringify(out, null, 2));

